let lastAudioState=null,audioError='',audioPanelPlace=null;
function audioGuide(p){if(p.audio)return {id:p.id,title:p.name,recorded:true,src:p.audio.src,duration:p.audio.duration,chapters:p.audio.chapters};return {id:p.id,title:p.name,chapters:[
  {title:'The building’s story',text:`Welcome to ${p.name}. ${p.story}`},
  {title:'Look a little closer',text:`While you’re here, try spotting these details. ${p.looks.map((s,i)=>`${['First','Next','Finally'][i]}, ${s.charAt(0).toLowerCase()+s.slice(1)}`).join(' ')}`},
  {title:'More to the story',text:p.culture.map(c=>`${c.title}. ${c.text}`).join(' ')}
]}}
function estimateAudio(text,rate=1){const seconds=Math.max(1,Math.round(text.trim().split(/\s+/).length/(145*rate)*60));return seconds>=60?`~${Math.floor(seconds/60)}m ${String(seconds%60).padStart(2,'0')}s`:`~${seconds}s`}
function formatSeconds(s){s=Math.max(1,Math.round(s));return s>=60?`${Math.floor(s/60)}m ${String(s%60).padStart(2,'0')}s`:`${s}s`}
function chapterTime(g,i,rate=1){if(!g.recorded)return estimateAudio(g.chapters[i].text,rate);const end=g.chapters[i+1]?.start??g.duration;return formatSeconds((end-g.chapters[i].start)/rate)}
function totalTime(g,rate=1){return g.recorded?formatSeconds(g.duration/rate):estimateAudio(g.chapters.map(c=>c.text).join(' '),rate)}
function rateOptions(){return [.8,1,1.2,1.5].map(r=>`<option value="${r}">${r}×</option>`).join('')}
// One line on a building's page: play, length, and a toggle for sections, speed and the transcript.
function audioPanel(p){const g=audioGuide(p),n=g.chapters.length;return `<section class="audio-panel audio-compact" id="audio-guide" aria-label="Audio guide for ${esc(p.name)}"><div class="audio-line"><button class="audio-primary" data-audio="play" data-place="${p.id}">${icon('play')}<span>Listen</span></button><span class="audio-meta">${icon('headphones')}<span><span class="audio-estimate">${totalTime(g)}</span> · ${n} ${n===1?'part':'parts'}</span></span><button class="audio-more-toggle" data-audio="more" aria-expanded="false" aria-controls="audio-more">Sections${icon('arrow')}</button></div><div class="audio-more" id="audio-more" hidden><div class="audio-sections" aria-label="Audio sections">${g.chapters.map((c,i)=>`<button class="audio-section" data-audio="chapter" data-place="${p.id}" data-chapter="${i}"><span class="audio-section-num">0${i+1}</span><span class="audio-section-title">${esc(c.title)}</span><span class="audio-section-time">${chapterTime(g,i)}</span>${icon('play')}</button>`).join('')}</div><div class="audio-settings"><label>Speed<select data-audio-setting="rate" aria-label="Audio playback speed">${rateOptions()}</select></label><label class="voice-label"${g.recorded?' hidden':''}>Voice<select data-audio-setting="voice" aria-label="Narration voice"><option value="">Device default</option></select></label></div><details class="audio-transcript"><summary>Read along · full transcript</summary>${g.chapters.map((c,i)=>`<div data-transcript-section="${i}"><h3>${esc(c.title)}</h3><p>${esc(c.text)}</p></div>`).join('')}</details><p class="audio-note">${g.recorded?'A recorded narration.':'Uses your device’s voice.'} Keep LookUp NYC open while listening.</p></div><p class="audio-error" role="status"></p></section>`}
const audioPreferences=readStore('lookup-audio-preferences',readStore('cityside-audio-preferences',{}));
const narrator=new LookUpAudio.Narrator({synth:window.speechSynthesis,Utterance:window.SpeechSynthesisUtterance,onChange:state=>{if(player===narrator)updateAudio(state)},onError:message=>{audioError=message;updateAudio(narrator.state());toast(message)}});
// One audio element, reused for every recording. Phones only let a page play sound that a tap started,
// so primeRecordedAudio() plays a moment of silence on it during a tap (Look Up mode's start button);
// later recordings, like the one that plays when you arrive at a stop, then play on the same element.
let sharedAudio=null;
const SILENCE='data:audio/wav;base64,';
function recordedElement(src){if(!sharedAudio)sharedAudio=new Audio();sharedAudio.src=src;return sharedAudio}
function primeRecordedAudio(){if(typeof Audio!=='function')return;try{if(!sharedAudio)sharedAudio=new Audio();if(recorded.el)return;sharedAudio.src=SILENCE;const r=sharedAudio.play();if(r&&r.catch)r.catch(()=>{})}catch{}}
const recorded=new LookUpAudio.RecordedPlayer({createAudio:typeof Audio==='function'?recordedElement:null,onChange:state=>{if(player===recorded)updateAudio(state)},onError:message=>{audioError=message;updateAudio(recorded.state());toast(message)}});
let player=narrator;
function playerFor(p){return p?.audio?recorded:narrator}
if(audioPreferences&&typeof audioPreferences==='object')[narrator,recorded].forEach(n=>n.configure({rate:[.8,1,1.2,1.5].includes(audioPreferences.rate)?audioPreferences.rate:1,voiceURI:typeof audioPreferences.voiceURI==='string'?audioPreferences.voiceURI:''}));
function populateVoices(){const voices=narrator.supported?narrator.synth.getVoices().filter(v=>/^en([-_]|$)/i.test(v.lang)):[];document.querySelectorAll('[data-audio-setting="voice"]').forEach(select=>{select.innerHTML='<option value="">Device default</option>'+voices.map(v=>`<option value="${esc(v.voiceURI)}">${esc(v.name)} (${esc(v.lang)})</option>`).join('');select.value=voices.some(v=>v.voiceURI===narrator.voiceURI)?narrator.voiceURI:''});}
function setupAudioPanel(){audioPanelPlace=document.querySelector('[data-audio="play"]')?.dataset.place||null;populateVoices();updateAudio(player.state());}
function updateAudio(state){
 lastAudioState=state;const panel=document.getElementById('audio-guide'),dock=document.getElementById('audio-dock');if(!dock)return;
 const isRunning=['playing','loading'].includes(state.phase),same=state.guide?.id===audioPanelPlace,panelPlayer=playerFor(byId(audioPanelPlace));
 document.querySelectorAll('[data-audio-setting="rate"]').forEach(s=>s.value=state.rate);
 if(panel){const guide=audioGuide(byId(audioPanelPlace));panel.querySelector('.audio-estimate').textContent=totalTime(guide,state.rate);panel.querySelectorAll('.audio-section-time').forEach((t,i)=>t.textContent=chapterTime(guide,i,state.rate));const play=panel.querySelector('[data-audio="play"]');play.innerHTML=icon(same&&isRunning?'pause':'play')+`<span>${same&&isRunning?(state.phase==='loading'?'Starting…':'Pause'):same&&state.phase==='paused'?'Resume':'Listen'}</span>`;play.disabled=!panelPlayer.supported;play.setAttribute('aria-label',same&&isRunning?'Pause audio guide':same&&state.phase==='paused'?'Resume audio guide':'Play audio guide');panel.querySelectorAll('[data-audio="chapter"]').forEach(b=>{const current=same&&Number(b.dataset.chapter)===state.chapter;b.classList.toggle('current',current);if(current)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');b.disabled=!panelPlayer.supported});panel.querySelector('.audio-error').textContent=!panelPlayer.supported?'Your browser does not support narration. The full transcript is below.':same?audioError:'';panel.querySelectorAll('[data-transcript-section]').forEach(s=>s.classList.toggle('reading',same&&Number(s.dataset.transcriptSection)===state.chapter));}
 if(!state.guide){dock.hidden=true;document.body.classList.remove('has-audio');return}
 dock.hidden=false;document.body.classList.add('has-audio');
 if(dock.dataset.place!==state.guide.id){dock.dataset.place=state.guide.id;dock.innerHTML=`<div class="audio-dock-art"><img src="assets/${state.guide.id}.webp" alt=""></div><div class="audio-dock-copy"><a href="#place/${state.guide.id}" class="audio-dock-title">${esc(state.guide.title)}</a><span class="audio-dock-subtitle"></span></div><div class="audio-dock-controls"><button data-audio="previous" aria-label="Previous audio section">${icon('previous')}</button><button data-audio="toggle" class="audio-dock-play" aria-label="Pause audio">${icon('pause')}</button><button data-audio="next" aria-label="Next audio section">${icon('next')}</button><button data-audio="close" class="audio-close" aria-label="Stop and close audio">×</button></div><div class="audio-dock-progress" role="progressbar" aria-label="Audio guide progress"><span></span></div>`}
 const status=state.phase==='playing'?'Playing':state.phase==='loading'?'Starting':state.phase==='paused'?'Paused':state.phase==='ended'?'Finished':state.phase==='error'?'Audio unavailable':'Ready';
 dock.querySelector('.audio-dock-subtitle').textContent=`${status} · ${state.chapter+1}/${state.guide.chapters.length} · ${state.guide.chapters[state.chapter].title}`;
 const toggle=dock.querySelector('[data-audio="toggle"]');toggle.innerHTML=icon(isRunning?'pause':state.phase==='ended'?'replay':'play');toggle.setAttribute('aria-label',isRunning?'Pause audio':state.phase==='ended'?'Replay audio guide':'Resume audio');
 dock.querySelector('[data-audio="previous"]').disabled=state.chapter===0;dock.querySelector('[data-audio="next"]').disabled=state.chapter===state.guide.chapters.length-1;
 const pct=state.total?state.completed/state.total*100:0,bar=dock.querySelector('.audio-dock-progress');bar.querySelector('span').style.width=pct+'%';bar.setAttribute('aria-valuemin','0');bar.setAttribute('aria-valuemax',state.total);bar.setAttribute('aria-valuenow',state.completed);bar.setAttribute('aria-valuetext',`${state.completed} of ${state.total} ${state.unit||'sentences'} completed`);
}
function launchAudio(id,chapter=0){const p=byId(id);if(!p)return;audioError='';const next=playerFor(p);if(next!==player){player.stop();player=next}player.load(audioGuide(p),chapter)}
document.addEventListener('click',e=>{const b=e.target.closest('[data-audio]');if(!b)return;const action=b.dataset.audio;audioError='';if(action==='play'){if(player.guide?.id===b.dataset.place&&['playing','loading','paused'].includes(player.phase))player.toggle();else launchAudio(b.dataset.place)}else if(action==='chapter')launchAudio(b.dataset.place,Number(b.dataset.chapter));else if(action==='toggle')player.toggle();else if(action==='previous')player.skip(player.chapter-1);else if(action==='next')player.skip(player.chapter+1);else if(action==='close')player.stop();else if(action==='tour-listen')launchAudio(b.dataset.place);else if(action==='more'){const m=document.getElementById('audio-more');if(!m)return;m.hidden=!m.hidden;b.setAttribute('aria-expanded',String(!m.hidden))}});
document.addEventListener('change',e=>{const setting=e.target.dataset.audioSetting;if(!setting)return;audioError='';[narrator,recorded].forEach(n=>n.configure(setting==='rate'?{rate:Number(e.target.value)}:{voiceURI:e.target.value}));putStore('lookup-audio-preferences',{rate:narrator.rate,voiceURI:narrator.voiceURI});});
window.speechSynthesis?.addEventListener('voiceschanged',populateVoices);window.addEventListener('pagehide',()=>{narrator.stop();recorded.stop()});
window.addEventListener('lookup:render',setupAudioPanel);render();
